    for r in routes:
        rr = []
        for c in r:
            if c != depot and c not in seen:
                rr.append(c)
                seen.add(c)
        if rr:
            final_routes.append(rr)

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    for c in missing:
        dem = demands[c]
        best_r = None
        best_pos = None
        best_cost = None
        for ridx in range(len(final_routes)):
            r = final_routes[ridx]
            load = 0
            for x in r:
                load += demands[x]
            if load + dem > capacity:
                continue
            for ins in range(len(r) + 1):
                prev = depot if ins == 0 else r[ins - 1]
                nxt = depot if ins == len(r) else r[ins]
                cost = d(prev, c) + d(c, nxt) - d(prev, nxt)
                if best_cost is None or cost < best_cost or (cost == best_cost and (ridx, ins) < (best_r, best_pos)):
                    best_cost = cost
                    best_r = ridx
                    best_pos = ins
        if best_r is None:
            final_routes.append([c])
        else:
            final_routes[best_r].insert(best_pos, c)

    return final_routes
